	'Кэшбэк пен сыйлық' => ['Кэшбэк и подарки', 'Cashback and gifts', 'Keshbek va sovgʻa', 'Кэшбэк жана белек'],
	'Күнделікті жұмысқа керектің бәрі' => ['Всё, что нужно для ежедневной работы', 'Everything you need for daily work', 'Kundalik ish uchun kerakli hammasi', 'Күнүмдүк ишке керектүүнүн баары'],
	'Артық күрделілігі жоқ, 5 тілде' => ['Без лишней сложности, на 5 языках', 'No needless complexity, in 5 languages', 'Ortiqcha murakkabliksiz, 5 tilda', 'Ашыкча татаалдыгы жок, 5 тилде'],
	'Жеткізу аймақтары' => ['Зоны доставки', 'Delivery zones', 'Yetkazish hududlari', 'Жеткирүү зоналары'],
	'Қала аймақтарға бөлінеді, әрқайсысына өз бағасы. Аймақ таңдалса, ақысы чекке өзі қосылады.' => ['Город делится на зоны, у каждой своя цена. Выбрали зону, и её цена сама добавилась в чек.', 'The city is split into zones, each with its own price. Pick a zone and the fee is added to the receipt.', 'Shahar hududlarga boʻlinadi, har birining oʻz narxi. Hudud tanlansa, narxi chekka oʻzi qoʻshiladi.', 'Шаар зоналарга бөлүнөт, ар биринин өз баасы. Зона тандалса, акысы чекке өзү кошулат.'],
	'Алдын ала тапсырыс' => ['Предзаказ', 'Pre-orders', 'Oldindan buyurtma', 'Алдын ала заказ'],
	'Ертеңге не белгілі уақытқа қабылдаңыз. Уақыты келгенде кухняға түседі.' => ['Принимайте на завтра или к нужному времени. В срок заказ сам попадёт на кухню.', 'Take orders for tomorrow or a set time. When it’s due, it goes to the kitchen.', 'Ertaga yoki belgilangan vaqtga qabul qiling. Vaqti kelganda oshxonaga tushadi.', 'Эртеңкиге же белгилүү убакытка кабыл алыңыз. Убактысы келгенде ашканага түшөт.'],
	'Накладнойды фотодан енгізесіз, сатылғанда шикізат қалдықтан өзі шегеріледі.' => ['Накладные вносите с фото, при продаже сырьё само списывается с остатков.', 'Enter invoices from a photo; ingredients are written off stock as you sell.', 'Nakladnoyni fotodan kiritasiz, sotilganda xomashyo qoldiqdan oʻzi chiqariladi.', 'Накладнойду сүрөттөн киргизесиз, сатылганда чийки зат калдыктан өзү кемийт.'],
	'Өзіндік құн' => ['Себестоимость', 'Food cost', 'Tannarx', 'Өздүк нарк'],
	'Әр тағамның құрамы, өзіндік құны мен пайдасы. Қайсысы табыс әкелетінін білесіз.' => ['Состав, себестоимость и прибыль каждого блюда. Вы знаете, что приносит доход.', 'Recipe, food cost and profit for every dish. You know what makes money.', 'Har bir taomning tarkibi, tannarxi va foydasi. Qaysi biri daromad keltirishini bilasiz.', 'Ар бир тамактын курамы, өздүк наркы жана пайдасы. Кайсынысы киреше алып келерин билесиз.'],
	'ОПиУ, РНП, ABC' => ['ОПиУ, РНП, ABC', 'P&L, plan, ABC', 'OPiU, RNP, ABC', 'ОПиУ, РНП, ABC'],
	'Күн, апта, ай, жыл бойынша түсім, шығын, пайда және қай тағам A тобында.' => ['Выручка, расходы, прибыль по дням, неделям, месяцам и годам, и какие блюда в группе A.', 'Revenue, expenses and profit by day, week, month and year, plus which dishes are in group A.', 'Kun, hafta, oy, yil boʻyicha tushum, xarajat, foyda va qaysi taom A guruhida.', 'Күн, апта, ай, жыл боюнча түшүм, чыгым, пайда жана кайсы тамак A тобунда.'],
	'Акция мен кэшбэк' => ['Акции и кэшбэк', 'Promotions and cashback', 'Aksiya va keshbek', 'Акция жана кэшбэк'],
	'Пайыздық жеңілдік, кэшбэк және әр N-ші тапсырысқа сыйлық.' => ['Скидка в процентах, кэшбэк и подарок за каждый N-й заказ.', 'Percentage discounts, cashback and a gift for every Nth order.', 'Foizli chegirma, keshbek va har N-buyurtmaga sovgʻa.', 'Пайыздык арзандатуу, кэшбэк жана ар бир N-заказга белек.'],
	'Интернетсіз касса' => ['Касса без интернета', 'POS without internet', 'Internetsiz kassa', 'Интернетсиз касса'],
	'Windows программасы интернет өшсе де сата береді, қосылғанда өзі жібереді.' => ['Программа для Windows продолжает продавать без интернета и сама отправит заказы при подключении.', 'The Windows app keeps selling when the internet drops and sends orders once it reconnects.', 'Windows dasturi internet oʻchsa ham sotaveradi, ulanganda oʻzi yuboradi.', 'Windows программасы интернет өчсө да сата берет, туташканда өзү жөнөтөт.'],
	'Мәзірді, сет құрамын және накладнойды фотодан өзі толтырады.' => ['Сам заполняет меню, состав сетов и накладные по фото.', 'Fills in menus, set contents and invoices from photos.', 'Menyu, set tarkibi va nakladnoyni fotodan oʻzi toʻldiradi.', 'Менюну, сет курамын жана накладнойду сүрөттөн өзү толтурат.'],
	'Барлық мүмкіндіктер' => ['Все возможности', 'All features', 'Barcha imkoniyatlar', 'Бардык мүмкүнчүлүктөр'],
	'Сіздің мекемеңізге қалай келеді' => ['Как это подходит вашему заведению', 'How it fits your place', 'Muassasangizga qanday mos keladi', 'Мекемеңизге кантип ылайык келет'],
	'Кафе мен асханаға' => ['Кафе и столовым', 'For cafes and canteens', 'Kafe va oshxonalar uchun', 'Кафе жана ашканаларга'],
	'Зал, өзімен алу, кухня экраны, өзіндік құн және ауысым есебі' => ['Зал, с собой, экран кухни, себестоимость и отчёт смены', 'Dine-in, takeaway, kitchen display, food cost and shift report', 'Zal, olib ketish, oshxona ekrani, tannarx va smena hisoboti', 'Зал, алып кетүү, ашкана экраны, өздүк нарк жана смена отчету'],
	'Доставка мен курьерге' => ['Доставке и курьерам', 'For delivery and couriers', 'Yetkazish va kuryerlar uchun', 'Жеткирүү жана курьерлерге'],
	'Курьер қосымшасы, жеткізу аймақтары және курьердің күндік есебі' => ['Приложение курьера, зоны доставки и дневной отчёт курьера', 'Courier app, delivery zones and courier daily report', 'Kuryer ilovasi, yetkazish hududlari va kuryerning kunlik hisoboti', 'Курьер тиркемеси, жеткирүү зоналары жана курьердин күндүк отчету'],
	'Тарифтер' => ['Тарифы', 'Pricing', 'Tariflar', 'Тарифтер'],
	'Алғашқы %d күн бәрі тегін. 6 айға төлесеңіз +1 ай, 12 айға +2 ай, 24 айға +6 ай сыйлық' => ['Первые %d дней всё бесплатно. При оплате за 6 месяцев +1 месяц, за 12 +2, за 24 +6 в подарок', 'The first %d days are free. Pay for 6 months and get +1, 12 months +2, 24 months +6 free', 'Dastlabki %d kun hammasi bepul. 6 oyga toʻlasangiz +1 oy, 12 oyga +2, 24 oyga +6 oy sovgʻa', 'Алгачкы %d күн баары акысыз. 6 айга төлөсөңүз +1 ай, 12 айга +2, 24 айга +6 ай белек'],
	'Тарифтерді салыстыру' => ['Сравнить тарифы', 'Compare plans', 'Tariflarni solishtirish', 'Тарифтерди салыштыруу'],
	'Қалай бастайсыз' => ['Как начать', 'How to start', 'Qanday boshlaysiz', 'Кантип баштайсыз'],
	'Тіркелу 2 минут, мәзірді енгізу бір кеш' => ['Регистрация 2 минуты, меню за один вечер', 'Sign-up takes 2 minutes, the menu one evening', 'Roʻyxatdan oʻtish 2 daqiqa, menyu bir kechada', 'Катталуу 2 мүнөт, менюну киргизүү бир кеч'],
	'Тіркелесіз' => ['Регистрируетесь', 'Sign up', 'Roʻyxatdan oʻtasiz', 'Катталасыз'],
	'Компания атауы, қала, телефон және пароль' => ['Название компании, город, телефон и пароль', 'Company name, city, phone and password', 'Kompaniya nomi, shahar, telefon va parol', 'Компаниянын аты, шаар, телефон жана сырсөз'],
	'Мәзірді енгізесіз' => ['Вносите меню', 'Add your menu', 'Menyuni kiritasiz', 'Менюну киргизесиз'],
	'Қолмен не фотодан ЖИ арқылы' => ['Вручную или по фото через ИИ', 'By hand or from a photo with AI', 'Qoʻlda yoki fotodan SI orqali', 'Кол менен же сүрөттөн ЖИ аркылуу'],
	'Қызметкер қосасыз' => ['Добавляете сотрудников', 'Add staff', 'Xodim qoʻshasiz', 'Кызматкер кошосуз'],
	'Кассир, аспаз, курьерге кіру береді' => ['Даёте доступ кассиру, повару, курьеру', 'Give access to cashiers, cooks, couriers', 'Kassir, oshpaz, kuryerga kirish berasiz', 'Кассирге, ашпозчуга, курьерге кирүү бересиз'],
	'Сата бастайсыз' => ['Начинаете продавать', 'Start selling', 'Sotishni boshlaysiz', 'Сата баштайсыз'],
	'Бірінші тапсырыс кассадан' => ['Первый заказ с кассы', 'First order from the POS', 'Birinchi buyurtma kassadan', 'Биринчи заказ кассадан'],
	'Жиі қойылатын сұрақтар' => ['Частые вопросы', 'Frequently asked questions', 'Koʻp beriladigan savollar', 'Көп берилүүчү суроолор'],
	'Қандай құрылғы керек?' => ['Какое оборудование нужно?', 'What hardware do I need?', 'Qanday qurilma kerak?', 'Кандай түзмөк керек?'],
	'Интернеті бар кез келген компьютер, планшет не моноблок. Курьер өз телефонынан жұмыс істейді. Бағдарлама браузерде ашылады, орнатудың қажеті жоқ.' => ['Любой компьютер, планшет или моноблок с интернетом. Курьер работает со своего телефона. Программа открывается в браузере, устанавливать ничего не нужно.', 'Any computer, tablet or all-in-one with internet. Couriers use their own phones. It runs in the browser, nothing to install.', 'Internetli istalgan kompyuter, planshet yoki monoblok. Kuryer oʻz telefonidan ishlaydi. Dastur brauzerda ochiladi, oʻrnatish shart emas.', 'Интернети бар каалаган компьютер, планшет же моноблок. Курьер өз телефонунан иштейт. Программа браузерде ачылат, орнотуунун кереги жок.'],
	'Интернет өшіп қалса не болады?' => ['Что будет, если пропадёт интернет?', 'What if the internet goes down?', 'Internet oʻchsa nima boʻladi?', 'Интернет өчүп калса эмне болот?'],
	'Деректер серверде сақталады, ештеңе жоғалмайды. Pro тарифінде Windows-қа арналған офлайн касса бар: интернетсіз сата береді, байланыс қалпына келгенде тапсырыстарды өзі жібереді.' => ['Данные хранятся на сервере, ничего не теряется. В тарифе Pro есть офлайн-касса для Windows: продаёт без интернета и сама отправит заказы, когда связь восстановится.', 'Data is stored on the server, nothing is lost. The Pro plan includes an offline POS for Windows that keeps selling and sends orders once the connection is back.', 'Maʼlumotlar serverda saqlanadi, hech narsa yoʻqolmaydi. Pro tarifida Windows uchun oflayn kassa bor: internetsiz sotadi, aloqa tiklanganda buyurtmalarni oʻzi yuboradi.', 'Маалыматтар серверде сакталат, эч нерсе жоголбойт. Pro тарифинде Windows үчүн офлайн касса бар: интернетсиз сатат, байланыш калыбына келгенде заказдарды өзү жөнөтөт.'],
	'Чек принтері қосыла ма?' => ['Можно подключить чековый принтер?', 'Can I connect a receipt printer?', 'Chek printeri ulanadimi?', 'Чек принтери туташабы?'],
	'Чек пен кухня тапсырысы кәдімгі чек принтерінен басылады. Чектің түрін админде өзіңіз баптайсыз.' => ['Чек и заказ для кухни печатаются на обычном чековом принтере. Вид чека настраиваете сами в админке.', 'Receipts and kitchen tickets print on a regular receipt printer. You design the receipt in the admin panel.', 'Chek va oshxona buyurtmasi oddiy chek printeridan chiqadi. Chek koʻrinishini adminda oʻzingiz sozlaysiz.', 'Чек жана ашкана заказы кадимки чек принтеринен басылат. Чектин түрүн админде өзүңүз тууралайсыз.'],
	'Бірнеше филиалды бір жерден басқаруға бола ма?' => ['Можно управлять несколькими филиалами из одного места?', 'Can I manage several branches from one place?', 'Bir nechta filialni bir joydan boshqarish mumkinmi?', 'Бир нече филиалды бир жерден башкарса болобу?'],
	'Иә, Max тарифінде. Әр филиалдың өз кассасы мен есебі болады, ал сіз бәрін бір жерден көресіз.' => ['Да, в тарифе Max. У каждого филиала своя касса и отчёты, а вы видите всё в одном месте.', 'Yes, on the Max plan. Each branch has its own POS and reports, and you see everything in one place.', 'Ha, Max tarifida. Har bir filialning oʻz kassasi va hisoboti boʻladi, siz esa hammasini bir joydan koʻrasiz.', 'Ооба, Max тарифинде. Ар бир филиалдын өз кассасы жана отчету болот, ал эми сиз баарын бир жерден көрөсүз.'],
	'Тегін кезеңнен кейін не болады?' => ['Что будет после пробного периода?', 'What happens after the trial?', 'Sinov davridan keyin nima boʻladi?', 'Сыноо мөөнөтүнөн кийин эмне болот?'],
	'%d күннен кейін ыңғайлы тарифті таңдап, Kaspi арқылы төлейсіз. Төлемесеңіз, деректеріңіз сақталады, бірақ жүйе ескерту көрсетеді.' => ['Через %d дней выбираете удобный тариф и оплачиваете через Kaspi. Если не оплатить, данные сохранятся, но система будет показывать напоминание.', 'After %d days you choose a plan and pay via Kaspi. If you don’t pay, your data stays, but the system shows a reminder.', '%d kundan keyin qulay tarifni tanlab, Kaspi orqali toʻlaysiz. Toʻlamasangiz, maʼlumotlaringiz saqlanadi, lekin tizim eslatma koʻrsatadi.', '%d күндөн кийин ыңгайлуу тарифти тандап, Kaspi аркылуу төлөйсүз. Төлөбөсөңүз, маалыматтарыңыз сакталат, бирок система эскертүү көрсөтөт.'],
	'Шақыру коды деген не?' => ['Что такое код приглашения?', 'What is a referral code?', 'Taklif kodi nima?', 'Чакыруу коду деген эмне?'],
	'Сізді біреу шақырса, сілтемедегі код тіркелу формасына өзі жазылады. Шақырған адам сіз төлеген айлардан бонус алады.' => ['Если вас кто-то пригласил, код из ссылки сам подставится в форму регистрации. Пригласивший получает бонус с оплаченных вами месяцев.', 'If someone invited you, the code from their link fills into the sign-up form. They earn a bonus from the months you pay for.', 'Sizni kimdir taklif qilsa, havoladagi kod roʻyxatdan oʻtish shakliga oʻzi yoziladi. Taklif qilgan kishi siz toʻlagan oylardan bonus oladi.', 'Сизди бирөө чакырса, шилтемедеги код каттоо формасына өзү жазылат. Чакырган адам сиз төлөгөн айлардан бонус алат.'],
	'Бүгін бастап көріңіз' => ['Начните уже сегодня', 'Start today', 'Bugun boshlang', 'Бүгүн баштаңыз'],
	'Форманы толтырасыз, компанияңыз бірден ашылады: касса, админ, филиал және %d күн тегін сынақ. Карта керек емес.' => ['Заполните форму, и компания откроется сразу: касса, админка, филиал и %d дней бесплатно. Карта не нужна.', 'Fill in the form and your company opens right away: POS, admin panel, branch and a %d-day free trial. No card needed.', 'Shaklni toʻldiring, kompaniyangiz darhol ochiladi: kassa, admin, filial va %d kun bepul sinov. Karta kerak emas.', 'Форманы толтуруңуз, компанияңыз дароо ачылат: касса, админ, филиал жана %d күн акысыз сыноо. Карта керек эмес.'],
