	'Телефон нөмірін толық жазыңыз' => ['Введите номер телефона полностью', 'Enter the full phone number', 'Telefon raqamini toʻliq yozing', 'Телефон номерин толук жазыңыз'],
	'Пароль кемінде 6 таңба болсын' => ['Пароль не короче 6 символов', 'Password must be at least 6 characters', 'Parol kamida 6 belgi boʻlsin', 'Сырсөз кеминде 6 белги болсун'],
	'Пароль тым ұзын' => ['Пароль слишком длинный', 'Password is too long', 'Parol juda uzun', 'Сырсөз өтө узун'],
	'Бұл нөмір жүйеде бар. Сол нөмірдің паролін жазыңыз не админде парольді қалпына келтіріңіз' => ['Этот номер уже есть в системе. Введите пароль от него или восстановите пароль в админке', 'This number is already registered. Enter its password or reset it in the admin panel', 'Bu raqam tizimda bor. Shu raqam parolini yozing yoki adminda parolni tiklang', 'Бул номер системада бар. Ошол номердин сырсөзүн жазыңыз же админде сырсөздү калыбына келтириңиз'],
	'Бұл нөмірге «%s» компаниясы тіркелген. Админге кіріңіз' => ['На этот номер уже зарегистрирована компания «%s». Войдите в админку', 'Company “%s” is already registered to this number. Log in to the admin panel', 'Bu raqamga «%s» kompaniyasi roʻyxatdan oʻtgan. Adminga kiring', 'Бул номерге «%s» компаниясы катталган. Админге кириңиз'],
	'Шақыру коды табылмады. Тексеріңіз не бос қалдырыңыз' => ['Код приглашения не найден. Проверьте или оставьте пустым', 'Referral code not found. Check it or leave it empty', 'Taklif kodi topilmadi. Tekshiring yoki boʻsh qoldiring', 'Чакыруу коду табылган жок. Текшериңиз же бош калтырыңыз'],
	'Сайттан тіркелді' => ['Зарегистрировался с сайта', 'Signed up on the website', 'Saytdan roʻyxatdan oʻtdi', 'Сайттан катталды'],
	'Тіркеу сәтсіз болды. Қайта көріңіз не WhatsApp-қа жазыңыз' => ['Не удалось зарегистрировать. Попробуйте ещё раз или напишите в WhatsApp', 'Sign-up failed. Try again or message us on WhatsApp', 'Roʻyxatdan oʻtkazib boʻlmadi. Qayta urinib koʻring yoki WhatsAppga yozing', 'Каттоо ишке ашкан жок. Кайра аракет кылыңыз же WhatsAppка жазыңыз'],
	'Байланыс | BERIK POS' => ['Контакты | BERIK POS', 'Contacts | BERIK POS', 'Aloqa | BERIK POS', 'Байланыш | BERIK POS'],
	'BERIK POS-пен байланыс: WhatsApp, телефон. Тіркелуге, мәзірді енгізуге және баптауға көмектесеміз.' => ['Связь с BERIK POS: WhatsApp, телефон. Поможем с регистрацией, меню и настройкой.', 'Contact BERIK POS: WhatsApp, phone. We help with sign-up, menu entry and setup.', 'BERIK POS bilan aloqa: WhatsApp, telefon. Roʻyxatdan oʻtish, menyu va sozlashda yordam beramiz.', 'BERIK POS менен байланыш: WhatsApp, телефон. Катталууга, менюга жана тууралоого жардам беребиз.'],
	'Сұрағыңыз болса, жазыңыз' => ['Есть вопрос? Напишите', 'Have a question? Write to us', 'Savolingiz bormi? Yozing', 'Сурооңуз барбы? Жазыңыз'],
	'Тіркелуге, мәзірді енгізуге, принтер мен кассаны баптауға көмектесеміз. Әдетте WhatsApp-қа 15 минут ішінде жауап береміз.' => ['Поможем зарегистрироваться, внести меню, настроить принтер и кассу. Обычно отвечаем в WhatsApp в течение 15 минут.', 'We help you sign up, add your menu, and set up the printer and POS. We usually reply on WhatsApp within 15 minutes.', 'Roʻyxatdan oʻtish, menyuni kiritish, printer va kassani sozlashda yordam beramiz. Odatda WhatsAppda 15 daqiqa ichida javob beramiz.', 'Катталууга, менюну киргизүүгө, принтер менен кассаны тууралоого жардам беребиз. Адатта WhatsAppта 15 мүнөттүн ичинде жооп беребиз.'],
	'Телефон' => ['Телефон', 'Phone', 'Telefon', 'Телефон'],
	'Өзіңіз бастаңыз' => ['Начните сами', 'Start on your own', 'Oʻzingiz boshlang', 'Өзүңүз баштаңыз'],
	'Тіркелу 2 минут, %d күн тегін' => ['Регистрация 2 минуты, %d дней бесплатно', 'Sign-up takes 2 minutes, %d days free', 'Roʻyxatdan oʻtish 2 daqiqa, %d kun bepul', 'Катталуу 2 мүнөт, %d күн акысыз'],
	'Доставкаға | BERIK POS' => ['Для доставки | BERIK POS', 'For delivery | BERIK POS', 'Yetkazish uchun | BERIK POS', 'Жеткирүү үчүн | BERIK POS'],
	'Курьер қосымшасы телефонда: тапсырыстар, мекенжай, төлем түрі. Жеткізу аймақтары және курьердің күндік есебі. %d күн тегін.' => ['Приложение курьера в телефоне: заказы, адрес, способ оплаты. Зоны доставки и дневной отчёт курьера. %d дней бесплатно.', 'Courier app on the phone: orders, address, payment type. Delivery zones and the courier’s daily report. %d days free.', 'Kuryer ilovasi telefonda: buyurtmalar, manzil, toʻlov turi. Yetkazish hududlari va kuryerning kunlik hisoboti. %d kun bepul.', 'Курьер тиркемеси телефондо: заказдар, дарек, төлөм түрү. Жеткирүү зоналары жана курьердин күндүк отчету. %d күн акысыз.'],
	'Жеткізуді ретке келтірейік' => ['Наведём порядок в доставке', 'Let’s get your delivery in order', 'Yetkazishni tartibga keltiramiz', 'Жеткирүүнү тартипке келтирели'],
	'Курьер тапсырысты телефоннан көреді, сіз ақшаны көресіз' => ['Курьер видит заказ в телефоне, вы видите деньги', 'The courier sees the order on the phone, you see the money', 'Kuryer buyurtmani telefonda koʻradi, siz pulni koʻrasiz', 'Курьер заказды телефондон көрөт, сиз акчаны көрөсүз'],
	'Мекенжай, клиент нөмірі, төлем түрі курьердің телефонында. Күн соңында кім неше тапсырыс жеткізгені және кассаға қанша тапсыратыны дайын тұрады.' => ['Адрес, номер клиента, способ оплаты в телефоне курьера. В конце дня готово, кто сколько доставил и сколько сдаёт в кассу.', 'Address, customer number and payment type are on the courier’s phone. At the end of the day you see who delivered how many orders and how much goes to the till.', 'Manzil, mijoz raqami, toʻlov turi kuryer telefonida. Kun oxirida kim nechta buyurtma yetkazgani va kassaga qancha topshirishi tayyor turadi.', 'Дарек, кардардын номери, төлөм түрү курьердин телефонунда. Күндүн аягында ким канча заказ жеткиргени жана кассага канча тапшырары даяр турат.'],
	'Курьер сөмкесі' => ['Сумка курьера', 'Courier bag', 'Kuryer sumkasi', 'Курьер сумкасы'],
	'Жеткізуде ең көп уақыт алатын үш сұрақ' => ['Три вопроса, на которые в доставке уходит больше всего времени', 'Three questions that eat the most time in delivery', 'Yetkazishda eng koʻp vaqt oladigan uchta savol', 'Жеткирүүдө эң көп убакыт алган үч суроо'],
	'Үшеуінің жауабы бір экранда' => ['Ответы на все три на одном экране', 'All three answered on one screen', 'Uchalasining javobi bitta ekranda', 'Үчөөнүн жообу бир экранда'],
	'«Курьер қайда?»' => ['«Где курьер?»', '“Where is the courier?”', '«Kuryer qayerda?»', '«Курьер кайда?»'],
	'Әр тапсырыстың күйі көрінеді: кухняда, жиналды, жолда, жеткізілді. Қай курьерде екені және қашан шыққаны жазылады.' => ['Видно состояние каждого заказа: на кухне, собран, в пути, доставлен. Записано, у какого курьера и когда выехал.', 'You see each order’s status: in the kitchen, packed, on the way, delivered. Which courier has it and when they left is recorded.', 'Har bir buyurtma holati koʻrinadi: oshxonada, yigʻildi, yoʻlda, yetkazildi. Qaysi kuryerda ekani va qachon chiqqani yoziladi.', 'Ар бир заказдын абалы көрүнөт: ашканада, чогултулду, жолдо, жеткирилди. Кайсы курьерде экени жана качан чыкканы жазылат.'],
	'«Ақша кімде?»' => ['«У кого деньги?»', '“Who has the money?”', '«Pul kimda?»', '«Акча кимде?»'],
	'Курьер жинаған қолма-қол мен Kaspi тапсырыс бойынша есептеледі, өз ақысы шегеріледі.' => ['Наличные и Kaspi, собранные курьером, считаются по заказам, его оплата вычитается.', 'Cash and Kaspi collected by the courier are counted per order, and their pay is deducted.', 'Kuryer yigʻgan naqd va Kaspi buyurtmalar boʻyicha hisoblanadi, uning haqi ayiriladi.', 'Курьер чогулткан накталай жана Kaspi заказ боюнча эсептелет, анын акысы кемитилет.'],
	'«Жеткізу қанша тұрады?»' => ['«Сколько стоит доставка?»', '“How much is delivery?”', '«Yetkazish qancha turadi?»', '«Жеткирүү канча турат?»'],
	'Қала аймақтарға бөлінеді. Кассир аймақты таңдаса, бағасы чекке өзі қосылады.' => ['Город делится на зоны. Кассир выбирает зону, и цена сама добавляется в чек.', 'The city is split into zones. The cashier picks a zone and the price is added to the receipt.', 'Shahar hududlarga boʻlinadi. Kassir hududni tanlasa, narx chekka oʻzi qoʻshiladi.', 'Шаар зоналарга бөлүнөт. Кассир зонаны тандаса, баасы чекке өзү кошулат.'],
	'Әр аймаққа өз бағасы мен уақыты' => ['У каждой зоны своя цена и время', 'Each zone has its own price and time', 'Har bir hududning oʻz narxi va vaqti', 'Ар бир зонанын өз баасы жана убактысы'],
	'Қаланы өзіңізге ыңғайлы аймақтарға бөлесіз. Белгілі сомадан асса, жеткізуді тегін етуге болады.' => ['Делите город на удобные зоны. От определённой суммы доставку можно сделать бесплатной.', 'Split the city into zones that suit you. Above a set amount, delivery can be free.', 'Shaharni qulay hududlarga boʻlasiz. Belgilangan summadan oshsa, yetkazishni bepul qilish mumkin.', 'Шаарды ыңгайлуу зоналарга бөлөсүз. Белгилүү суммадан ашса, жеткирүүнү акысыз кылса болот.'],
	'Аймақ' => ['Зона', 'Zone', 'Hudud', 'Зона'],
	'Баға' => ['Цена', 'Price', 'Narx', 'Баасы'],
	'Уақыт' => ['Время', 'Time', 'Vaqt', 'Убакыт'],
	'Тегін' => ['Бесплатно от', 'Free from', 'Bepul', 'Акысыз'],
	'1-аймақ, орталық' => ['Зона 1, центр', 'Zone 1, center', '1-hudud, markaz', '1-зона, борбор'],
	'2-аймақ' => ['Зона 2', 'Zone 2', '2-hudud', '2-зона'],
	'3-аймақ, шеткі' => ['Зона 3, окраина', 'Zone 3, outskirts', '3-hudud, chekka', '3-зона, чет жака'],
	'Қала сырты' => ['За городом', 'Out of town', 'Shahar tashqarisi', 'Шаардан тышкары'],
	'Мысал. Аймақтар мен бағаларды админде өзіңіз қоясыз' => ['Пример. Зоны и цены вы задаёте в админке', 'Example. You set zones and prices in the admin panel', 'Misol. Hudud va narxlarni adminda oʻzingiz qoʻyasiz', 'Мисал. Зоналар менен бааларды админде өзүңүз коёсуз'],
	'Курьердің күндік есебі' => ['Дневной отчёт курьера', 'Courier daily report', 'Kuryerning kunlik hisoboti', 'Курьердин күндүк отчету'],
	'Кешке ақшаны санап отырмайсыз' => ['Вечером не нужно пересчитывать деньги', 'No counting money in the evening', 'Kechqurun pul sanab oʻtirmaysiz', 'Кечинде акча санап отурбайсыз'],
	'Ауысым соңында әр курьер бойынша есеп шығады. Kaspi курьерге түсетіндіктен, ол да жиналған ақшаға кіреді. Есеп сақталады, кейін ашып қарауға болады.' => ['В конце смены выходит отчёт по каждому курьеру. Kaspi приходит курьеру, поэтому тоже входит в собранные деньги. Отчёт сохраняется, его можно открыть позже.', 'At the end of the shift there is a report for every courier. Kaspi payments go to the courier, so they count as collected money too. Reports are saved for later.', 'Smena oxirida har bir kuryer boʻyicha hisobot chiqadi. Kaspi kuryerga tushgani uchun u ham yigʻilgan pulga kiradi. Hisobot saqlanadi, keyin ochib koʻrish mumkin.', 'Смена аягында ар бир курьер боюнча отчет чыгат. Kaspi курьерге түшкөндүктөн, ал да чогулган акчага кирет. Отчет сакталат, кийин ачып көрсө болот.'],
	'Курьер тек өз тапсырыстарын көреді' => ['Курьер видит только свои заказы', 'Couriers see only their own orders', 'Kuryer faqat oʻz buyurtmalarini koʻradi', 'Курьер өз заказдарын гана көрөт'],
	'Клиентке бір басумен қоңырау' => ['Звонок клиенту в одно касание', 'Call the customer in one tap', 'Mijozga bir bosishda qoʻngʻiroq', 'Кардарга бир басуу менен чалуу'],
	'Қосымша орнатпайды, браузерде ашылады' => ['Ничего не устанавливать, открывается в браузере', 'Nothing to install, it opens in the browser', 'Hech narsa oʻrnatilmaydi, brauzerda ochiladi', 'Эч нерсе орнотулбайт, браузерде ачылат'],
	'Жеткізілген тапсырыс' => ['Доставлено заказов', 'Orders delivered', 'Yetkazilgan buyurtma', 'Жеткирилген заказ'],
	'Курьер ақысы' => ['Оплата курьера', 'Courier pay', 'Kuryer haqi', 'Курьердин акысы'],
	'Кассаға' => ['В кассу', 'To the till', 'Kassaga', 'Кассага'],
	'Мысал есеп. Кассаға = жиналған қолма-қол мен Kaspi, минус курьер ақысы' => ['Пример. В кассу = собранные наличные и Kaspi минус оплата курьера', 'Example. To the till = cash and Kaspi collected minus courier pay', 'Misol. Kassaga = yigʻilgan naqd va Kaspi, minus kuryer haqi', 'Мисал. Кассага = чогулган накталай жана Kaspi, минус курьердин акысы'],
	'Мүмкіндіктер | BERIK POS' => ['Возможности | BERIK POS', 'Features | BERIK POS', 'Imkoniyatlar | BERIK POS', 'Мүмкүнчүлүктөр | BERIK POS'],
	'BERIK POS модульдері: касса, кухня, раздача, курьер, админ, склад, өзіндік құн, ОПиУ, РНП, QR мәзір, акциялар, офлайн касса және ЖИ көмекшісі.' => ['Модули BERIK POS: касса, кухня, раздача, курьер, админка, склад, себестоимость, ОПиУ, РНП, QR-меню, акции, офлайн-касса и ИИ-помощник.', 'BERIK POS modules: POS, kitchen, dispatch, courier, admin, stock, food cost, P&L, sales plan, QR menu, promotions, offline POS and AI assistant.', 'BERIK POS modullari: kassa, oshxona, tarqatish, kuryer, admin, ombor, tannarx, OPiU, RNP, QR menyu, aksiyalar, oflayn kassa va SI yordamchi.', 'BERIK POS модулдары: касса, ашкана, тарату, курьер, админ, кампа, өздүк нарк, ОПиУ, РНП, QR меню, акциялар, офлайн касса жана ЖИ жардамчы.'],
	'Сату' => ['Продажи', 'Sales', 'Savdo', 'Сатуу'],
	'Тапсырысты қабылдаудан чекке дейін' => ['От приёма заказа до чека', 'From order to receipt', 'Buyurtma qabul qilishdan chekkacha', 'Заказ кабыл алуудан чекке чейин'],
	'Зал, өзімен алу, жеткізу, алдын ала тапсырыс. Бір экранда бірнеше касса қатары, төлемді бөлу, алдын ала төлем.' => ['Зал, с собой, доставка, предзаказ. Несколько касс на одном экране, разделение оплаты, предоплата.', 'Dine-in, takeaway, delivery, pre-orders. Several tills on one screen, split payments, prepayment.', 'Zal, olib ketish, yetkazish, oldindan buyurtma. Bitta ekranda bir nechta kassa, toʻlovni boʻlish, oldindan toʻlov.', 'Зал, алып кетүү, жеткирүү, алдын ала заказ. Бир экранда бир нече касса, төлөмдү бөлүү, алдын ала төлөм.'],
	'Чек редакторы' => ['Редактор чека', 'Receipt editor', 'Chek muharriri', 'Чек редактору'],
	'Чекке логотип, мекенжай, QR және өз мәтініңізді қосасыз. Касса өзі басып шығарады.' => ['Добавьте в чек логотип, адрес, QR и свой текст. Касса печатает сама.', 'Add your logo, address, QR and own text to the receipt. The POS prints it.', 'Chekka logotip, manzil, QR va oʻz matningizni qoʻshasiz. Kassa oʻzi chop etadi.', 'Чекке логотип, дарек, QR жана өз текстиңизди кошосуз. Касса өзү басып чыгарат.'],
	'Ауысым ашқанда кассадағы ақша жазылады, жапқанда қолма-қол, Kaspi, карта бойынша есеп шығады.' => ['При открытии смены фиксируются деньги в кассе, при закрытии выходит отчёт по наличным, Kaspi и картам.', 'Opening a shift records the cash float; closing it gives a report by cash, Kaspi and card.', 'Smena ochilganda kassadagi pul yoziladi, yopilganda naqd, Kaspi, karta boʻyicha hisobot chiqadi.', 'Смена ачылганда кассадагы акча жазылат, жабылганда накталай, Kaspi, карта боюнча отчет чыгат.'],
	'Офлайн касса' => ['Офлайн-касса', 'Offline POS', 'Oflayn kassa', 'Офлайн касса'],
	'Windows программасы интернетсіз сатады, байланыс келгенде тапсырыстарды серверге өзі жібереді.' => ['Программа для Windows продаёт без интернета и сама отправляет заказы на сервер, когда связь вернётся.', 'The Windows app sells without internet and sends orders to the server once the connection is back.', 'Windows dasturi internetsiz sotadi, aloqa tiklanganda buyurtmalarni serverga oʻzi yuboradi.', 'Windows программасы интернетсиз сатат, байланыш келгенде заказдарды серверге өзү жөнөтөт.'],
	'Кухня мен раздача' => ['Кухня и раздача', 'Kitchen and dispatch', 'Oshxona va tarqatish', 'Ашкана жана тарату'],
	'Тапсырыс кезекпен, ешнәрсе ұмытылмайды' => ['Заказы по очереди, ничего не забыто', 'Orders in sequence, nothing forgotten', 'Buyurtmalar navbat bilan, hech narsa unutilmaydi', 'Заказдар кезек менен, эч нерсе унутулбайт'],
	'Жаңа тапсырыс бірден шығады, қайсысы неше минут күтіп тұрғаны көрінеді. «Дайын» бір батырмамен.' => ['Новый заказ появляется сразу, видно, сколько минут ждёт каждый. «Готово» одной кнопкой.', 'New orders appear instantly with how long each has waited. “Ready” with one button.', 'Yangi buyurtma darhol chiqadi, qaysi biri necha daqiqa kutayotgani koʻrinadi. «Tayyor» bitta tugma bilan.', 'Жаңы заказ дароо чыгат, кайсынысы канча мүнөт күтүп турганы көрүнөт. «Даяр» бир баскыч менен.'],
	'Дайын тапсырыстар бір жерде: курьерге тағайындау, залға беру, өзі алып кетуге шақыру.' => ['Готовые заказы в одном месте: назначить курьеру, отдать в зал, позвать на самовывоз.', 'Ready orders in one place: assign to a courier, serve to a table, call for pickup.', 'Tayyor buyurtmalar bir joyda: kuryerga biriktirish, zalga berish, olib ketishga chaqirish.', 'Даяр заказдар бир жерде: курьерге дайындоо, залга берүү, алып кетүүгө чакыруу.'],
	'Стоп-лист' => ['Стоп-лист', 'Stop list', 'Stop-list', 'Стоп-лист'],
	'Біткен тағамды кухня белгілейді, касса мен QR мәзірде «Қазір жоқ» болып көрінеді.' => ['Закончившееся блюдо отмечает кухня, в кассе и QR-меню оно показывается как «Нет в наличии».', 'The kitchen marks dishes that run out, and the POS and QR menu show them as “Not available”.', 'Tugagan taomni oshxona belgilaydi, kassa va QR menyuda «Hozir yoʻq» boʻlib koʻrinadi.', 'Түгөнгөн тамакты ашкана белгилейт, касса менен QR менюда «Азыр жок» болуп көрүнөт.'],
	'Курьер мен ақша бақылауда' => ['Курьеры и деньги под контролем', 'Couriers and cash under control', 'Kuryer va pul nazoratda', 'Курьер жана акча көзөмөлдө'],
	'Курьер телефонынан өз тапсырыстарын, мекенжайды, төлем түрін көреді. Орнатудың қажеті жоқ.' => ['Курьер видит в телефоне свои заказы, адрес и способ оплаты. Ничего устанавливать не нужно.', 'Couriers see their orders, address and payment type on their phone. Nothing to install.', 'Kuryer telefonidan oʻz buyurtmalarini, manzilni, toʻlov turini koʻradi. Oʻrnatish shart emas.', 'Курьер телефонунан өз заказдарын, даректи, төлөм түрүн көрөт. Орнотуунун кереги жок.'],
	'Әр аймаққа өз бағасы мен уақыты, белгілі сомадан бастап тегін жеткізу.' => ['У каждой зоны своя цена и время, бесплатная доставка от определённой суммы.', 'Each zone has its own price and time, with free delivery above a set amount.', 'Har bir hududning oʻz narxi va vaqti, belgilangan summadan bepul yetkazish.', 'Ар бир зонанын өз баасы жана убактысы, белгилүү суммадан акысыз жеткирүү.'],
	'Курьер не жинады, өз ақысы қанша, кассаға қанша тапсырады, күн соңында дайын.' => ['Что собрал курьер, сколько его оплата, сколько сдаёт в кассу, к концу дня готово.', 'What the courier collected, their pay, and what goes to the till, ready by the end of the day.', 'Kuryer nima yigʻdi, haqi qancha, kassaga qancha topshiradi, kun oxirida tayyor.', 'Курьер эмне чогултту, акысы канча, кассага канча тапшырат, күндүн аягында даяр.'],
	'Склад және өзіндік құн' => ['Склад и себестоимость', 'Stock and food cost', 'Ombor va tannarx', 'Кампа жана өздүк нарк'],
	'Накладной' => ['Накладная', 'Invoice', 'Nakladnoy', 'Накладной'],
	'Жеткізушіден келген тауар фотодан не Excel-ден енгізіледі, бағасы өзі жаңарады.' => ['Товар от поставщика вносится с фото или из Excel, цена обновляется сама.', 'Supplier goods are entered from a photo or Excel and prices update automatically.', 'Yetkazib beruvchidan kelgan tovar fotodan yoki Exceldan kiritiladi, narxi oʻzi yangilanadi.', 'Жеткирүүчүдөн келген товар сүрөттөн же Excelден киргизилет, баасы өзү жаңыланат.'],
	'Қалдық' => ['Остатки', 'Stock levels', 'Qoldiq', 'Калдык'],
	'Тағам сатылғанда шикізат складтан өзі шегеріледі. Ревизия мен шығын есебі.' => ['При продаже блюда сырьё списывается со склада само. Ревизия и учёт списаний.', 'When a dish sells, ingredients are written off stock automatically. Stocktakes and waste tracking.', 'Taom sotilganda xomashyo ombordan oʻzi chiqariladi. Reviziya va isrof hisobi.', 'Тамак сатылганда чийки зат кампадан өзү кемийт. Ревизия жана чыгым эсеби.'],
	'Себес (өзіндік құн)' => ['Себестоимость', 'Food cost', 'Tannarx', 'Өздүк нарк'],
	'Граммовка шаблондары, жартылай фабрикат, әр тағамның өзіндік құны мен маржасы.' => ['Шаблоны граммовки, полуфабрикаты, себестоимость и маржа каждого блюда.', 'Portion templates, semi-finished items, food cost and margin for every dish.', 'Grammovka shablonlari, yarim tayyor mahsulot, har bir taom tannarxi va marjasi.', 'Граммовка шаблондору, жарым фабрикат, ар бир тамактын өздүк наркы жана маржасы.'],
	'Клиент және маркетинг' => ['Клиенты и маркетинг', 'Customers and marketing', 'Mijoz va marketing', 'Кардар жана маркетинг'],
	'Клиент қайта келсін' => ['Чтобы клиент возвращался', 'Bring customers back', 'Mijoz qayta kelsin', 'Кардар кайра келсин'],
	'Үстелдегі QR-дан мәзір ашылады, клиент өзі тапсырыс береді. 17 дизайн шаблоны.' => ['Меню открывается по QR на столе, клиент заказывает сам. 17 шаблонов дизайна.', 'The menu opens from the QR on the table and guests order themselves. 17 design templates.', 'Stoldagi QR orqali menyu ochiladi, mijoz oʻzi buyurtma beradi. 17 ta dizayn shabloni.', 'Столдогу QRдан меню ачылат, кардар өзү заказ берет. 17 дизайн шаблону.'],
	'Клиенттер базасы' => ['База клиентов', 'Customer base', 'Mijozlar bazasi', 'Кардарлар базасы'],
	'Нөмір, мекенжай, тапсырыс тарихы. Келесі жолы касса бірден толтырады.' => ['Номер, адрес, история заказов. В следующий раз касса заполнит сразу.', 'Number, address, order history. Next time the POS fills it in at once.', 'Raqam, manzil, buyurtmalar tarixi. Keyingi safar kassa darhol toʻldiradi.', 'Номер, дарек, заказ тарыхы. Кийинки жолу касса дароо толтурат.'],
	'Акция, кэшбэк, сыйлық' => ['Акции, кэшбэк, подарки', 'Promotions, cashback, gifts', 'Aksiya, keshbek, sovgʻa', 'Акция, кэшбэк, белек'],
	'Пайыздық жеңілдік, сатылымға қарай кэшбэк, әр N-ші тапсырысқа сыйлық.' => ['Скидка в процентах, кэшбэк от суммы, подарок за каждый N-й заказ.', 'Percentage discounts, cashback by spend, a gift for every Nth order.', 'Foizli chegirma, savdoga qarab keshbek, har N-buyurtmaga sovgʻa.', 'Пайыздык арзандатуу, сатууга жараша кэшбэк, ар бир N-заказга белек.'],
	'Басқару және есеп' => ['Управление и отчёты', 'Management and reports', 'Boshqaruv va hisobot', 'Башкаруу жана отчет'],
	'Бизнесті сандармен көресіз' => ['Видите бизнес в цифрах', 'See your business in numbers', 'Biznesni raqamlarda koʻrasiz', 'Бизнести сандар менен көрөсүз'],
	'Күн, апта, ай, жыл бойынша түсім, чек саны, орташа чек, төлем түрлері.' => ['Выручка, число чеков, средний чек, способы оплаты по дням, неделям, месяцам и годам.', 'Revenue, receipt count, average check and payment types by day, week, month and year.', 'Kun, hafta, oy, yil boʻyicha tushum, cheklar soni, oʻrtacha chek, toʻlov turlari.', 'Күн, апта, ай, жыл боюнча түшүм, чек саны, орточо чек, төлөм түрлөрү.'],
	'ОПиУ мен РНП' => ['ОПиУ и РНП', 'P&L and sales plan', 'OPiU va RNP', 'ОПиУ жана РНП'],
	'Кіріс, шығын, таза пайда және апталық-айлық жоспар орындалуы.' => ['Доходы, расходы, чистая прибыль и выполнение недельного и месячного плана.', 'Income, expenses, net profit and progress on weekly and monthly plans.', 'Daromad, xarajat, sof foyda va haftalik-oylik reja bajarilishi.', 'Киреше, чыгаша, таза пайда жана апталык-айлык пландын аткарылышы.'],
	'ABC анализ' => ['ABC-анализ', 'ABC analysis', 'ABC tahlil', 'ABC анализ'],
	'Тағамдар түсімі, саны және маржасы бойынша A, B, C топтарына бөлінеді.' => ['Блюда делятся на группы A, B, C по выручке, количеству и марже.', 'Dishes are split into A, B and C groups by revenue, quantity and margin.', 'Taomlar tushum, soni va marja boʻyicha A, B, C guruhlarga boʻlinadi.', 'Тамактар түшүм, саны жана маржасы боюнча A, B, C топторуна бөлүнөт.'],
	'Филиалдар' => ['Филиалы', 'Branches', 'Filiallar', 'Филиалдар'],
	'Бірнеше филиал бір кабинетте, әрқайсысының есебі бөлек.' => ['Несколько филиалов в одном кабинете, отчёт по каждому отдельно.', 'Several branches in one account, each with its own report.', 'Bir nechta filial bitta kabinetda, har birining hisoboti alohida.', 'Бир нече филиал бир кабинетте, ар биринин отчету өзүнчө.'],
	'Мәзірді, сет құрамын, накладнойды фотодан өзі толтырады.' => ['Сам заполняет меню, состав сетов и накладные по фото.', 'Fills in menus, set contents and invoices from photos.', 'Menyu, set tarkibi va nakladnoyni fotodan oʻzi toʻldiradi.', 'Менюну, сет курамын, накладнойду сүрөттөн өзү толтурат.'],
	'5 тіл' => ['5 языков', '5 languages', '5 til', '5 тил'],
	'Қазақша, орысша, ағылшынша, өзбекше, қырғызша. Әр қызметкер өз тілін таңдайды.' => ['Казахский, русский, английский, узбекский, кыргызский. Каждый сотрудник выбирает свой язык.', 'Kazakh, Russian, English, Uzbek, Kyrgyz. Each employee picks their own language.', 'Qozoq, rus, ingliz, oʻzbek, qirgʻiz. Har bir xodim oʻz tilini tanlaydi.', 'Казак, орус, англис, өзбек, кыргыз. Ар бир кызматкер өз тилин тандайт.'],
	'Кафе жұмысының әр бөлігіне бір модуль' => ['Модуль для каждой части работы кафе', 'A module for every part of running a cafe', 'Kafe ishining har bir qismi uchun modul', 'Кафе ишинин ар бир бөлүгүнө бир модуль'],
	'Барлық модуль бір базада жұмыс істейді. Тегін сынақта %d күн бәрі ашық, сосын керек тарифті таңдайсыз.' => ['Все модули работают в одной базе. В пробный период %d дней всё открыто, потом выбираете нужный тариф.', 'All modules share one database. Everything is open during the %d-day trial, then you choose a plan.', 'Barcha modullar bitta bazada ishlaydi. Bepul sinovda %d kun hammasi ochiq, keyin kerakli tarifni tanlaysiz.', 'Бардык модулдар бир базада иштейт. Акысыз сыноодо %d күн баары ачык, андан кийин керектүү тарифти тандайсыз.'],
	'Тарифтер | BERIK POS' => ['Тарифы | BERIK POS', 'Pricing | BERIK POS', 'Tariflar | BERIK POS', 'Тарифтер | BERIK POS'],
	'BERIK POS тарифтері: Start 9 990 ₸, Pro 29 990 ₸, Max 59 990 ₸ айына. %d күн тегін, ұзақ мерзімге сыйлық айлар.' => ['Тарифы BERIK POS: Start 9 990 ₸, Pro 29 990 ₸, Max 59 990 ₸ в месяц. %d дней бесплатно, подарочные месяцы за долгий срок.', 'BERIK POS pricing: Start 9 990 ₸, Pro 29 990 ₸, Max 59 990 ₸ per month. %d days free, bonus months for longer terms.', 'BERIK POS tariflari: Start 9 990 ₸, Pro 29 990 ₸, Max 59 990 ₸ oyiga. %d kun bepul, uzoq muddatga sovgʻa oylar.', 'BERIK POS тарифтери: Start 9 990 ₸, Pro 29 990 ₸, Max 59 990 ₸ айына. %d күн акысыз, узак мөөнөткө белек айлар.'],
	'Кафеңіздің көлеміне қарай тариф' => ['Тариф под размер вашего кафе', 'A plan for the size of your cafe', 'Kafengiz hajmiga qarab tarif', 'Кафеңиздин көлөмүнө жараша тариф'],
	'Тіркелгенде %d күн бойы барлық модуль тегін ашылады. Сосын керек тарифті таңдап, Kaspi арқылы төлейсіз.' => ['После регистрации все модули открыты бесплатно на %d дней. Потом выбираете тариф и оплачиваете через Kaspi.', 'After sign-up all modules are free for %d days. Then you choose a plan and pay via Kaspi.', 'Roʻyxatdan oʻtgach %d kun davomida barcha modullar bepul ochiladi. Keyin kerakli tarifni tanlab, Kaspi orqali toʻlaysiz.', 'Катталганда %d күн бою бардык модулдар акысыз ачылат. Андан кийин керектүү тарифти тандап, Kaspi аркылуу төлөйсүз.'],
	'Модульдерді салыстыру' => ['Сравнение модулей', 'Compare modules', 'Modullarni solishtirish', 'Модулдарды салыштыруу'],
	'Әр тариф алдыңғысының бәрін қамтиды' => ['Каждый тариф включает всё из предыдущего', 'Each plan includes everything in the one before', 'Har bir tarif oldingisining hammasini oʻz ichiga oladi', 'Ар бир тариф мурункусунун баарын камтыйт'],
	'Модуль' => ['Модуль', 'Module', 'Modul', 'Модуль'],
	'Касса, филиал, тағам және ай сайынғы тапсырыс лимиттері тарифке байланысты. Нақтысын тіркелгеннен кейін «Оплата» бетінде көресіз.' => ['Лимиты касс, филиалов, блюд и заказов в месяц зависят от тарифа. Точные цифры увидите после регистрации на странице «Оплата».', 'Limits on tills, branches, dishes and monthly orders depend on the plan. You’ll see exact figures on the “Payment” page after sign-up.', 'Kassa, filial, taom va oylik buyurtma limitlari tarifga bogʻliq. Aniqlarini roʻyxatdan oʻtgach «Toʻlov» sahifasida koʻrasiz.', 'Касса, филиал, тамак жана айлык заказ лимиттери тарифке байланыштуу. Тагын катталгандан кийин «Төлөм» бетинде көрөсүз.'],
	'Ұзақ мерзімге сыйлық айлар' => ['Подарочные месяцы за долгий срок', 'Bonus months for longer terms', 'Uzoq muddatga sovgʻa oylar', 'Узак мөөнөткө белек айлар'],
	'Жеңілдік емес, қосымша тегін ай' => ['Не скидка, а дополнительные бесплатные месяцы', 'Not a discount, extra free months', 'Chegirma emas, qoʻshimcha bepul oy', 'Арзандатуу эмес, кошумча акысыз ай'],
	'ай' => ['мес', 'mo', 'oy', 'ай'],
	'6 айға төлесеңіз, 7 ай қолданасыз' => ['Оплатите 6 месяцев и пользуйтесь 7', 'Pay for 6 months, use 7', '6 oyga toʻlasangiz, 7 oy foydalanasiz', '6 айга төлөсөңүз, 7 ай колдоносуз'],
	'12 айға төлесеңіз, 14 ай қолданасыз' => ['Оплатите 12 месяцев и пользуйтесь 14', 'Pay for 12 months, use 14', '12 oyga toʻlasangiz, 14 oy foydalanasiz', '12 айга төлөсөңүз, 14 ай колдоносуз'],
	'24 айға төлесеңіз, 30 ай қолданасыз' => ['Оплатите 24 месяца и пользуйтесь 30', 'Pay for 24 months, use 30', '24 oyga toʻlasangiz, 30 oy foydalanasiz', '24 айга төлөсөңүз, 30 ай колдоносуз'],
	'Төлем туралы' => ['Об оплате', 'About payment', 'Toʻlov haqida', 'Төлөм жөнүндө'],
	'Қалай төлеймін?' => ['Как оплатить?', 'How do I pay?', 'Qanday toʻlayman?', 'Кантип төлөйм?'],
	'Админдегі «Оплата» бетінде Kaspi QR бар. Төлеп, чекті WhatsApp-қа жібересіз, мерзім ұзартылады.' => ['На странице «Оплата» в админке есть Kaspi QR. Оплатите и отправьте чек в WhatsApp, срок продлится.', 'The “Payment” page in the admin panel has a Kaspi QR. Pay, send the receipt on WhatsApp, and your term is extended.', 'Admindagi «Toʻlov» sahifasida Kaspi QR bor. Toʻlab, chekni WhatsAppga yuborasiz, muddat uzaytiriladi.', 'Админдеги «Төлөм» бетинде Kaspi QR бар. Төлөп, чекти WhatsAppка жөнөтөсүз, мөөнөт узартылат.'],
	'Тарифті кейін ауыстыруға бола ма?' => ['Можно сменить тариф позже?', 'Can I change plans later?', 'Tarifni keyin almashtirish mumkinmi?', 'Тарифти кийин алмаштырса болобу?'],
	'Иә, кез келген уақытта. Жаңа тариф келесі төлемнен бастап қолданылады.' => ['Да, в любое время. Новый тариф действует со следующей оплаты.', 'Yes, anytime. The new plan applies from the next payment.', 'Ha, istalgan vaqtda. Yangi tarif keyingi toʻlovdan boshlab amal qiladi.', 'Ооба, каалаган убакта. Жаңы тариф кийинки төлөмдөн баштап колдонулат.'],
	'Сынақ біткенде деректер өшіп қала ма?' => ['Удалятся ли данные после пробного периода?', 'Is my data deleted after the trial?', 'Sinov tugagach maʼlumotlar oʻchib ketadimi?', 'Сыноо бүткөндө маалыматтар өчүп калабы?'],
	'Жоқ. Мәзір, тапсырыстар мен есептер сақталады. Төлегеннен кейін жұмысты сол жерден жалғастырасыз.' => ['Нет. Меню, заказы и отчёты сохраняются. После оплаты продолжаете с того же места.', 'No. Menus, orders and reports are kept. After paying you continue where you left off.', 'Yoʻq. Menyu, buyurtmalar va hisobotlar saqlanadi. Toʻlagandan keyin ishni shu joydan davom ettirasiz.', 'Жок. Меню, заказдар жана отчеттор сакталат. Төлөгөндөн кийин ишти ошол жерден улантасыз.'],
	'Шақыру бонусы қалай есептеледі?' => ['Как считается бонус за приглашение?', 'How is the referral bonus calculated?', 'Taklif bonusi qanday hisoblanadi?', 'Чакыруу бонусу кантип эсептелет?'],
	'Сіз шақырған компания төлеген әр айдан бонус аласыз: алғашқы 3 айда 30%, 12-айға дейін 10%, 24-айға дейін 5%, кейін 1%. Бонуспен өз жазылымыңызды төлей аласыз.' => ['С каждого месяца, оплаченного приглашённой компанией, вы получаете бонус: первые 3 месяца 30%, до 12-го месяца 10%, до 24-го 5%, дальше 1%. Бонусом можно оплатить свою подписку.', 'You earn a bonus from every month the invited company pays: 30% for the first 3 months, 10% up to month 12, 5% up to month 24, then 1%. You can pay your own subscription with the bonus.', 'Siz taklif qilgan kompaniya toʻlagan har oydan bonus olasiz: dastlabki 3 oyda 30%, 12-oygacha 10%, 24-oygacha 5%, keyin 1%. Bonus bilan oʻz obunangizni toʻlashingiz mumkin.', 'Сиз чакырган компания төлөгөн ар бир айдан бонус аласыз: алгачкы 3 айда 30%, 12-айга чейин 10%, 24-айга чейин 5%, андан кийин 1%. Бонус менен өз жазылууңузду төлөй аласыз.'],
	'Қате сұрау' => ['Неверный запрос', 'Invalid request', 'Notoʻgʻri soʻrov', 'Туура эмес суроо'],
	'Тіркеу уақытша жұмыс істемейді. WhatsApp-қа жазыңыз' => ['Регистрация временно недоступна. Напишите в WhatsApp', 'Sign-up is temporarily unavailable. Message us on WhatsApp', 'Roʻyxatdan oʻtish vaqtincha ishlamayapti. WhatsAppga yozing', 'Каттоо убактылуу иштебей жатат. WhatsAppка жазыңыз'],
	'Тым көп әрекет. Кейінірек көріңіз не WhatsApp-қа жазыңыз' => ['Слишком много попыток. Попробуйте позже или напишите в WhatsApp', 'Too many attempts. Try later or message us on WhatsApp', 'Juda koʻp urinish. Keyinroq urinib koʻring yoki WhatsAppga yozing', 'Өтө көп аракет. Кийинчерээк аракет кылыңыз же WhatsAppка жазыңыз'],
	'Шарттармен келісуіңіз керек' => ['Нужно согласиться с условиями', 'Please accept the terms', 'Shartlarga rozi boʻlishingiz kerak', 'Шарттарга макул болушуңуз керек'],
	'Код тым жиі сұралды. 15 минуттан кейін көріңіз' => ['Код запрашивали слишком часто. Попробуйте через 15 минут', 'Code requested too often. Try again in 15 minutes', 'Kod juda koʻp soʻraldi. 15 daqiqadan keyin urinib koʻring', 'Код өтө көп суралды. 15 мүнөттөн кийин аракет кылыңыз'],
